function UICultivateEquipReplaceTipDialog:RefreshUI(parameters)
    local titleName = parameters.titleName
    self:RefreshTitleText(titleName)

    ---@type CardComponent
    local cardComp       = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    ---@type EquipmentComponent
    local equipComp      = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local usedCardIdList = parameters.usedCardIdList or {}

    local count    = #usedCardIdList
    --print(table.toString(usedCardIdList))
    --local rowCount = math.ceil(count / 3)

    --for i = 1, rowCount do
    --    KTool.SetActive(self[string.format("LineImage%s", i)], true)
    --end

    local EquipTipNode  = self.EquipTipNode
    local EquipTipNodes = self.EquipTipNodes
    for i = 1, count do
        local data = usedCardIdList[i]
        local playerCardId, id, part = data.playerCardId, data.id, data.part
        local node = EquipTipNodes.gameObject:AddChild(EquipTipNode.gameObject)
        local transform = node.transform
        KTool.SetActive(node, true)

        local refId
        local isCore = part == -1
        if part == -1 then
            local equipmentCoreDojo = equipComp:GetEquipCoreById(id)
            refId = equipmentCoreDojo.equipmentCoreId
        else
            local equipDojo = equipComp:GetEquipById(id)
            refId = equipDojo.equipmentId
            local equipVo = cardConfMgr:GetEquipVoById(refId)
            part = equipVo.part
        end

        local EquipNode = transform:Find("EquipNode")
        self:RefreshGoodsNode(EquipNode, id, refId)

        local CoreText = transform:Find("CoreText")
        KTool.SetActive(CoreText.gameObject, isCore)

        --local MarkIcon = transform:Find("MarkIcon")
        --KTool.SetActive(MarkIcon.gameObject, not isCore)
        --if not isCore then
        --    CfUtils.SetUISwitchImage(MarkIcon, part)
        --end

        local LinkIcon = transform:Find("LinkIcon")
        local isShowCard = checkNumber(playerCardId) > 0
        KTool.SetActive(LinkIcon.gameObject, isShowCard)
        local CardNode  = transform:Find("CardNode")
        KTool.SetActive(CardNode.gameObject, isShowCard)
        if isShowCard then
            local cardDojo  = cardComp:GetCardById(playerCardId)
            self:RefreshCardNode(CardNode, cardDojo)

        end

    end

    --if rowCount == 1 then
    --    --- 修正背景大小
    --    local y = self.MainNode.sizeDelta.y - EquipTipNodes.sizeDelta.y * 0.5
    --    self.BG:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, y)
    --    self.MainNode:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, y)
    --end

end

---RefreshTitleText
---刷新标题名称
---@param titleName string 标题名称
function UICultivateEquipReplaceTipDialog:RefreshTitleText(titleName)
    if titleName == nil then
        titleName = localize("以下情绪涂鸦已被使用，是否替换？")
    end

    self.TitleText.text = titleName
end

---RefreshGoodsNode
---@param node UnityEngine.RectTransform   GoodNode Prefab
---@param id      number                   道具数据库id
---@param goodsId number                   道具id
function UICultivateEquipReplaceTipDialog:RefreshGoodsNode(node, id, goodsId)
    local Env = CfUtils.GetLuaScr(node, GoodsNodeMBPath)
    if isNull(Env) then
        return
    end
    Env:Reload({
        id = id,
        goodsId = goodsId,
    })
    Env:SetClickCallback(function()
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        local rare = goodsVo.quality
        GameUtils.ShowCommonTipsBoard(node.gameObject, goodsVo.name, goodsVo.desc, rare, goodsId)
    end)
    local reScale = node.gameObject:GetComponent(typeof(ReverseScale))
    if reScale then
        reScale:ResetScale()
    end
end

function UICultivateEquipReplaceTipDialog:RefreshCardNode(node, cardDojo)
    ---@type CardHeadNode
    local Env = CfUtils.GetLuaScr(node, CardHeadNodePath)
    if isNull(Env) then return end
    Env:FreshNode(cardDojo, true)
end

